<?php
namespace ExcelHerbal\ERP7\Organization;
use ExcelHerbal\ERP7\Security\DesignationDefaults;use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\BranchAuthority;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;use ExcelHerbal\ERP7\Security\HierarchyScope;
final class OrganizationBranchService{
 public static function branches(Actor $a):array{if(!$a->branchIds)return[];$ids=implode(',',array_map('intval',$a->branchIds));return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT id,code,name,is_head_office,status FROM ".Db::table('branches')." WHERE company_id=%d AND id IN ({$ids}) AND status='active' ORDER BY is_head_office DESC,name",$a->companyId),ARRAY_A);}
 public static function createBranch(Actor $a,string $code,string $name,bool $headOffice=false):array{Guard::cap($a,Capabilities::BRANCH_MANAGE);$code=strtoupper(trim($code));$name=trim($name);if($code===''||$name==='')throw new DomainException('Branch code and name are required.');if(strlen($code)>50||strlen($name)>190)throw new DomainException('Branch code or name is too long.','branch_fields_invalid',422);return Transaction::run(function()use($a,$code,$name,$headOffice){$db=Db::wpdb();$t=Db::table('branches');if($headOffice&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND status='active' AND is_head_office=1 FOR UPDATE",$a->companyId)))throw new DomainException('An active Head Office branch already exists.','head_office_exists',409);Db::mustInsert($db,$t,['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'is_head_office'=>$headOffice?1:0,'status'=>'active','created_at'=>Db::now()],'Branch code already exists.','branch_duplicate');$id=(int)$db->insert_id;Db::mustInsert($db,Db::table('employee_branch_authorities'),['company_id'=>$a->companyId,'employee_id'=>$a->employeeId,'branch_id'=>$id,'active'=>1,'granted_by'=>$a->employeeId,'valid_from'=>Db::now(),'valid_until'=>null]);Audit::add($a,'branch.create','branch',$id,['branch_id'=>$id,'code'=>$code,'creator_authority_bootstrapped'=>true]);return['id'=>$id,'code'=>$code,'name'=>$name,'status'=>'active'];});}
 public static function setBranchAuthority(Actor $a,int $employeeId,int $branch,bool $active):array{Guard::branch($a,$branch,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();$e=$db->get_var($db->prepare("SELECT id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d",$employeeId,$a->companyId));if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);$t=Db::table('employee_branch_authorities');$r=$db->get_row($db->prepare("SELECT id FROM {$t} WHERE company_id=%d AND employee_id=%d AND branch_id=%d",$a->companyId,$employeeId,$branch),ARRAY_A);$data=['active'=>$active?1:0,'granted_by'=>$a->employeeId,'valid_from'=>Db::now(),'valid_until'=>null];if($r)Db::mustUpdate($db,$t,$data,['id'=>(int)$r['id']]);elseDb::mustInsert($db,$t,['company_id'=>$a->companyId,'employee_id'=>$employeeId,'branch_id'=>$branch]+$data);Audit::add($a,'branch_authority.'.($active?'grant':'revoke'),'employee',$employeeId,['branch_id'=>$branch]);return['employee_id'=>$employeeId,'branch_id'=>$branch,'active'=>$active,'branch_ids'=>BranchAuthority::ids($employeeId,$a->companyId)];}
 public static function updateBranch(Actor $a,int $branchId,array $data):array{
  Guard::cap($a,Capabilities::BRANCH_MANAGE);$db=Db::wpdb();$t=Db::table('branches');$b=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d",$branchId,$a->companyId),ARRAY_A);if(!$b)throw new DomainException('Branch not found.','branch_not_found',404);if((string)$b['status']==='active'&&!$a->hasBranch($branchId))throw new DomainException('Branch is outside effective authority.','branch_forbidden',403);
  $chg=[];if(array_key_exists('code',$data)){$code=strtoupper(trim((string)$data['code']));if($code===''||strlen($code)>50)throw new DomainException('Valid branch code is required.','branch_fields_invalid',422);$exists=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND code=%s AND id<>%d",$a->companyId,$code,$branchId));if($exists)throw new DomainException('Branch code already exists.','branch_duplicate',409);$chg['code']=$code;}if(array_key_exists('name',$data)){$name=trim((string)$data['name']);if($name===''||strlen($name)>190)throw new DomainException('Valid branch name is required.','branch_fields_invalid',422);$chg['name']=$name;}if(!$chg)throw new DomainException('No editable branch fields supplied.','parameter_required',422);Db::mustUpdate($db,$t,$chg,['id'=>$branchId,'company_id'=>$a->companyId]);Audit::add($a,'branch.update','branch',$branchId,$chg);return['id'=>$branchId]+$chg+['status'=>(string)$b['status']];
 }
 public static function setBranchStatus(Actor $a,int $branchId,bool $active):array{
  Guard::cap($a,Capabilities::BRANCH_MANAGE);$db=Db::wpdb();$t=Db::table('branches');$b=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$branchId,$a->companyId),ARRAY_A);if(!$b)throw new DomainException('Branch not found.','branch_not_found',404);$target=$active?'active':'inactive';if((string)$b['status']===$target)return['id'=>$branchId,'status'=>$target];if(!$active){if((int)$b['is_head_office']===1)throw new DomainException('Head Office branch cannot be deactivated.','head_office_deactivate_blocked',409);$emp=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('employees')." WHERE company_id=%d AND assigned_branch_id=%d AND status='active'",$a->companyId,$branchId));$qty=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(quantity),0) FROM ".Db::table('stock_balances')." WHERE company_id=%d AND branch_id=%d AND quantity>0",$a->companyId,$branchId));$daily=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_cycles')." WHERE company_id=%d AND branch_id=%d AND status<>'completed'",$a->companyId,$branchId));if($emp||$qty>.0001||$daily)throw new DomainException('Branch has active employees, stock, or incomplete Daily Orders.','branch_deactivate_blocked',409);$transfers=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_transfers')." WHERE company_id=%d AND (source_branch_id=%d OR destination_branch_id=%d) AND status NOT IN ('received','cancelled')",$a->companyId,$branchId,$branchId));if($transfers)throw new DomainException('Branch has open stock transfers.','branch_deactivate_blocked',409);}Db::mustUpdate($db,$t,['status'=>$target],['id'=>$branchId,'company_id'=>$a->companyId]);Audit::add($a,'branch.status','branch',$branchId,['status'=>$target]);return['id'=>$branchId,'status'=>$target];
 }
}
